:root {
  --ink: #1f2d36;
  --muted: #4a5a64;
  --paper: #f6f4ef;
  --line: #d9d4c7;
  --accent: #1d5a73;
  --accent-dark: #143f51;
}

* {
  box-sizing: border-box;
}

html {
  font-size: 112.5%;
}

body {
  margin: 0;
  background: var(--paper);
  color: var(--ink);
  font-family: system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  line-height: 1.6;
}

main,
footer {
  max-width: 36rem;
  margin: 0 auto;
  padding: 0 1.25rem;
}

main {
  padding-top: 3rem;
  padding-bottom: 2.5rem;
}

h1,
h2 {
  font-family: Georgia, "Times New Roman", serif;
  font-weight: normal;
  line-height: 1.25;
}

h1 {
  font-size: 2rem;
  margin: 0 0 1rem;
}

h2 {
  font-size: 1.3rem;
  margin: 2.25rem 0 0.5rem;
}

p,
li {
  max-width: 34rem;
}

.lede {
  font-size: 1.1rem;
  color: var(--muted);
}

.signup {
  display: inline-block;
  margin: 1.25rem 0 0.5rem;
  padding: 0.85rem 1.5rem;
  min-height: 44px;
  background: var(--accent);
  color: #ffffff;
  text-decoration: none;
  border-radius: 4px;
  font-weight: 600;
}

.signup:hover {
  background: var(--accent-dark);
}

a:focus-visible {
  outline: 3px solid var(--ink);
  outline-offset: 3px;
}

.note {
  font-size: 0.9rem;
  color: var(--muted);
}

a {
  color: var(--accent);
}

ul {
  padding-left: 1.2rem;
}

footer {
  border-top: 1px solid var(--line);
  padding-top: 1rem;
  padding-bottom: 2rem;
  font-size: 0.9rem;
  color: var(--muted);
}

footer a {
  margin-right: 1rem;
}

@media (min-width: 48rem) {
  main {
    padding-top: 5rem;
  }

  h1 {
    font-size: 2.5rem;
  }
}

